\label{thm:mainSU2}
Assume \eqref{eq:H}, $G=\mathrm{SU}(2)$, and $X\cong S^3$. Then the action is one of the following equivariant diffeomorphism types:
\begin{enumerate}
\item the linear action on $S(\mathbb C^2\oplus\mathfrak{su}(2))\cong S^6$;
\item $N^G_{1,1}$ or $N^G_{2j-1,2j+1}$, $j\ge1$, on $S^2\times S^4$;
\item the standard block action on $F_{\mathrm W}$;
\item the commuting right block action on $F_{\mathrm E}$.
\end{enumerate}
The only genuine exceptional stratum in the three-singular-orbit case is one $C_3$ interval, and its presence characterizes (iv). Consequently the middle panel of Liu's Figure~4 has labels $(1,1)$ or $(1,3)$, and the right panel has $(1,1,1)$ or $(1,1,3)$, up to permutation and deletion of labels~$1$. The surviving three-orbit patterns have positive-curvature realizations. For the two-orbit patterns, the displayed weights are necessary conditions; invariant strict positivity is not established here.

\label{lem:normal}
An oriented equivariant normal two-plane bundle $\nu$ of $A_m$ is determined by its oriented endpoint characters $u,v\in\mathbb Z$. They must satisfy $v\equiv u\pmod m$, and its Euler class obeys
\begin{equation}\label{eq:evaluations}
 \langle e(\nu),[S_-]\rangle=d_Gu,\quad
 \langle e(\nu),[S_+]\rangle=d_Gv,\quad
 \langle e(\nu),[f]\rangle=\frac{v-u}{m}.
\end{equation}
The unit circle bundle of $\nu$ is simply connected if and only if
\begin{equation}\label{eq:primitive}
 \gcd\left(d_Gu,\frac{v-u}{m}\right)=1.
\end{equation}

\label{prop:localization}
There are signs $\varepsilon_i\in\{1,-1\}$ determined by the tangent orientations such that
\begin{align}
 0&=\sum_i\frac{\varepsilon_i n_i(x)}{p_iq_i},\label{eq:lin}\\
 \mu_M(x,y,z)&=\frac1{d_G^2}\sum_i
 \frac{\varepsilon_i n_i(x)n_i(y)n_i(z)}{p_iq_i},\label{eq:cub}\\
 p_M(x)&=\sum_i\frac{\varepsilon_i n_i(x)
 (4/d_G^2+p_i^2+q_i^2)}{p_iq_i}.\label{eq:pon}
\end{align}
The rational evaluation map $H^2(M;\mathbb Q)\to\mathbb Q^r$ is injective. When $\chi(M)=2r$, its image is exactly the hyperplane \eqref{eq:lin}.

\label{prop:ballb}
In case~(b), $k=2n$ is even, and the underlying manifold is $E_n=S(\xi_n)\to S^4$ with $p_1(\xi_n)=4n u$. Its integral data, in compatible generators $x\in H^2(M)$ and $y\in H^4(M)$, are
\begin{equation}\label{eq:Eninvariants}
 \begin{gathered}
 H^{\mathrm{odd}}(M;\mathbb Z)=0,\quad H^2(M)=H^4(M)=\mathbb Z,\quad
 \int_Mxy=1,\quad x^2=ny,\\
 w_2(M)=0,\qquad p_1(M)=4ny.
 \end{gathered}
\end{equation}
Every integer $n$ is smoothly realizable in this stratum, and the ordinary diffeomorphism type is determined by $|n|$.

\label{thm:Mk}
For odd $k$, the homology of $M_k$ is torsion-free, $b_2=b_4=2$, and $H^{\mathrm{odd}}(M_k;\mathbb Z)=0$. There is a basis $x,y$ of $H^2(M_k;\mathbb Z)$ restricting to $a,b$ on $F$ such that
\begin{align}
 \int_{M_k}x^3&=\frac{k^3-k}{4},&
 \int_{M_k}x^2y&=\frac{1-k^2}{2},&
 \int_{M_k}xy^2&=k,&
 \int_{M_k}y^3&=-2,\label{eq:Mkcubic}\\
 w_2(M_k)&=\bar y,&&\operatorname{PD}[F]=2x+ky,\label{eq:Mkw2}\\
 \int_{M_k}p_1(M_k)x&=3k,&&
 \int_{M_k}p_1(M_k)y=-2.\label{eq:Mkp1}
\end{align}
Moreover $M_k\cong M_\ell$ if and only if $|k|=|\ell|$, and every $M_k$ is rationally elliptic.

\label{thm:matching}
Suppose an open exceptional edge has isotropy $C_k$, $k>1$ odd, and transverse slice $\mathbb R\oplus\mathbb C_s$. Then
\begin{equation}\label{eq:matching}
 s\equiv\pm2\pmod k.
\end{equation}
Consequently, an exceptional edge incident to a one-valent singular vertex has order three.

\label{prop:boundaryidentity}
For orthonormal orbit vectors $U,V$ and $h$-orthonormal base vectors $X,Y$, the ambient sectional curvatures along $F$ satisfy
\begin{align}
 K_g(U,V)&=\frac{1-|df|_h^2}{f^2},\label{eq:boundaryvertical}\\
 K_g(X,Y)&=K_h,\label{eq:boundarybase}\\
 K_g(U,X)&=-\frac{\operatorname{Hess}_hf(X,X)}{f}+|\beta(X)|^2.\label{eq:boundarymixed}
\end{align}
These identities concern the indicated planes, not all planes in $TM|_F$.

\label{cor:boundaryobstruction}
If $g$ is invariant under \eqref{eq:SO3productaction} and $\operatorname{sec}_g>0$, then
\begin{equation}\label{eq:boundarynecessary}
 K_h>0,\qquad |df|_h<1,\qquad
 \mathcal S:=\beta^*\beta-f^{-1}\operatorname{Hess}_hf>0.
\end{equation}
The form $\beta_b:T_bB\to\mathbb C$ is a real-linear isomorphism at every minimum of $f$, and at every degeneracy point it satisfies
\[
 \operatorname{Hess}_hf(X,X)<0\quad\text{for all }0\ne X\in\ker\beta_b.
\]
In particular no such positive metric has constant singular-orbit radius, or has $\operatorname{rank}_{\mathbb R}\beta\le1$ everywhere. In addition,
\begin{equation}\label{eq:boundaryenergy}
 \int_B|\beta|_h^2\,dA_h>
 \int_B|d\log f|_h^2\,dA_h.
\end{equation}
If $\operatorname{sec}_g\ge\kappa>0$, the right-hand side can be increased by $2\kappa\operatorname{Area}(B,h)$, with $\ge$ in place of $>$.
